export function getPageForSurahAndAyah(surahNumber: number, ayahNumber: number): number {
  let bestPage = 1;
  for (let p = 0; p < PAGE_BOUNDARIES.length; p++) {
    const [s, a] = PAGE_BOUNDARIES[p];
    if (s < surahNumber || (s === surahNumber && a <= ayahNumber)) {
      bestPage = p + 1;
    } else {
      break;
    }
  }
  return bestPage;
}
